// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Uint64 } from '@stdlib/types/number';
import { Collection, NumericArray } from '@stdlib/types/array';

/**
* Interface for computing the bitwise XOR of two 64-bit unsigned integers.
*/
interface RightShift {
	/**
	* Performs bitwise shift to the right on a 64-bit unsigned integer.
	*
	* @param a - 64-bit unsigned integer
	* @param shift - number of bits to shift (0-63)
	* @returns result
	*
	* @example
	* var Uint64 = require( '@stdlib/number/uint64/ctor' );
	*
	* var a = new Uint64( 10 );
	*
	* var v = rightShift( a, 1 );
	* // returns <Uint64>[ 5n ]
	*/
	( a: Uint64, shift: number ): Uint64;

	/**
	* Performs bitwise shift to the right on a 64-bit unsigned integer and assigns results to a provided output array.
	*
	* @param ah - high 32-bit word of the 64-bit unsigned integer
	* @param al - low 32-bit word of the 64-bit unsigned integer
	* @param shift - number of bits to shift (0-63)
	* @param out - output array
	* @param stride - stride length
	* @param offset - starting index
	* @returns output array
	*
	* @example
	* var Uint32Array = require( '@stdlib/array/uint32' );
	*
	* var out = rightShift.assign( 2, 4, 1, new Uint32Array( 2 ), 1, 0 );
	* // returns <Uint32Array>[ 1, 2 ]
	*/
	assign<T extends NumericArray | Collection<number>>( ah: number, al: number, shift: number, out: T, stride: number, offset: number ): T;

	/**
	* Performs bitwise shift to the right on a 64-bit unsigned integer stored in integer-valued strided array views and assigns results to a provided strided output array.
	*
	* @param a - 64-bit unsigned integer strided array view containing interleaved 32-bit unsigned integer high and low order words
	* @param sa - stride length for `a`
	* @param oa - starting index for `a`
	* @param shift - number of bits to shift (0-63)
	* @param out - output array
	* @param so - stride length for `out`
	* @param oo - starting index for `out`
	* @returns output array
	*
	* @example
	* var Uint32Array = require( '@stdlib/array/uint32' );
	*
	* var a = new Uint32Array( [ 2, 4 ] );
	*
	* var out = rightShift.strided( a, 1, 0, 1, new Uint32Array( 2 ), 1, 0 );
	* // returns <Uint32Array>[ 1, 2 ]
	*/
	strided<T extends NumericArray | Collection<number>, U extends NumericArray | Collection<number>>( a: T, sa: number, oa: number, shift: number, out: U, so: number, oo: number ): U;
}

/**
* Performs bitwise shift to the right on a 64-bit unsigned integer.
*
* @param a - 64-bit unsigned integer
* @param shift - number of bits to shift (0-63)
* @returns result
*
* @example
* var Uint64 = require( '@stdlib/number/uint64/ctor' );
*
* var a = new Uint64( 10 );
*
* var v = rightShift( a, 1 );
* // returns <Uint64>[ 5n ]
*
* @example
* var Uint32Array = require( '@stdlib/array/uint32' );
*
* var out = rightShift.assign( 2, 4, 1, new Uint32Array( 2 ), 1, 0 );
* // returns <Uint32Array>[ 1, 2 ]
*
* @example
* var Uint32Array = require( '@stdlib/array/uint32' );
*
* var a = new Uint32Array( [ 2, 4 ] );
*
* var out = rightShift.strided( a, 1, 0, 1, new Uint32Array( 2 ), 1, 0 );
* // returns <Uint32Array>[ 1, 2 ]
*/
declare var rightShift: RightShift;


// EXPORTS //

export = rightShift;
